fn human_apply_one<R: tauri::Runtime>(
    app: &AppHandle<R>,
    p: &EvolutionProposal,
    embedding: Option<&[f32]>,
) -> Result<ApplyOutcome, String> {
    // 调用方持 EVOLUTION_STORE_LOCK；这里不重入 DB_WRITE_LOCK — store→DB 反向嵌套会与
